<?php

declare(strict_types=1);

require_once __DIR__.'/Database.php';
require_once __DIR__.'/Auth.php';
require_once __DIR__.'/AccessPolicy.php';
require_once __DIR__.'/AppNavigation.php';
require_once __DIR__.'/VolunteerVerificationService.php';

final class VolunteerVerificationExperience
{
    private const ROUTES=['/volunteer/verifications','/volunteer/verification','/admin/volunteer-verification'];
    public static function handles(string $route):bool{return in_array($route,self::ROUTES,true);}
    public static function render(string $route,string $basePath):never
    {
        Auth::startSession();$db=Database::connect(dirname(__DIR__));$user=Auth::currentUser($db);if(!$user)self::redirect($basePath.'/login');$_SESSION['volunteer_verification_csrf']??=bin2hex(random_bytes(24));
        if($route==='/volunteer/verification'){$id=filter_input(INPUT_GET,'id',FILTER_VALIDATE_INT)?:0;if(!VolunteerVerificationService::canViewVerification($db,$user,(int)$id)){http_response_code(404);exit('Verification unavailable.');}$v=VolunteerVerificationService::verification($db,(int)$id);self::letter($basePath,$user,$v,isset($_GET['print']));}
        if($route==='/admin/volunteer-verification'){if(!AccessPolicy::canManageVolunteers($user)){http_response_code(403);exit('Volunteer management permission is required.');}if($_SERVER['REQUEST_METHOD']==='POST')self::adminPost($db,$basePath,$user);self::adminPage($db,$basePath,$user);}
        self::memberPage($db,$basePath,$user);
    }
    private static function adminPost(PDO $db,string $basePath,array $user):never
    {
        if(!hash_equals((string)($_SESSION['volunteer_verification_csrf']??''),(string)($_POST['csrf_token']??''))){self::flash('error','Your session token expired.');self::redirect($basePath.'/admin/volunteer-verification');}
        try{
            $action=(string)($_POST['action']??'');$uid=filter_input(INPUT_POST,'user_id',FILTER_VALIDATE_INT)?:0;
            if($action==='issue'){$id=VolunteerVerificationService::issue($db,$user,(int)$uid,(string)($_POST['period_start']??''),(string)($_POST['period_end']??''),trim((string)($_POST['purpose']??''))?:null);self::flash('success','Verified service record issued.');self::redirect($basePath.'/volunteer/verification?id='.$id);}
            elseif($action==='coordinator'){VolunteerVerificationService::assignCoordinator($db,$user,(int)$uid,filter_input(INPUT_POST,'production_id',FILTER_VALIDATE_INT)?:null,(string)($_POST['title']??''),trim((string)($_POST['category']??''))?:null);self::flash('success','Coordinator role assigned.');}
            elseif($action==='credential'){self::verifyCredential($db,$user,(int)$uid,(int)(filter_input(INPUT_POST,'requirement_id',FILTER_VALIDATE_INT)?:0),(string)($_POST['completed_at']??''),(string)($_POST['expires_at']??''),trim((string)($_POST['note']??''))?:null);self::flash('success','Volunteer requirement verified. Shift eligibility updates immediately.');}
            else throw new RuntimeException('Choose a valid action.');
        }catch(RuntimeException $e){self::flash('error',$e->getMessage());}
        self::redirect($basePath.'/admin/volunteer-verification');
    }
    private static function verifyCredential(PDO $db,array $actor,int $userId,int $requirementId,string $completed,string $expires,?string $note):void
    {
        if($userId<1||$requirementId<1)throw new RuntimeException('Choose a volunteer and requirement.');
        $vol=$db->prepare("SELECT u.id,CONCAT(u.first_name,' ',u.last_name) name FROM users u JOIN volunteer_profiles vp ON vp.user_id=u.id AND vp.active=1 WHERE u.id=:user AND u.active=1 LIMIT 1");$vol->execute(['user'=>$userId]);$volunteer=$vol->fetch();if(!$volunteer)throw new RuntimeException('That active volunteer could not be found.');
        $req=$db->prepare('SELECT id,code,name,category,expires FROM volunteer_requirements WHERE id=:id LIMIT 1');$req->execute(['id'=>$requirementId]);$requirement=$req->fetch();if(!$requirement)throw new RuntimeException('That volunteer requirement no longer exists.');
        $completedDate=DateTimeImmutable::createFromFormat('Y-m-d',trim($completed));if(!$completedDate)throw new RuntimeException('Choose the date the requirement was completed or verified.');
        $expiresAt=null;if(trim($expires)!==''){$expiry=DateTimeImmutable::createFromFormat('Y-m-d',trim($expires));if(!$expiry)throw new RuntimeException('Enter a valid expiration date.');if($expiry<$completedDate)throw new RuntimeException('Expiration cannot be before the completion date.');$expiresAt=$expiry->format('Y-m-d 23:59:59');}
        if((bool)$requirement['expires']&&$expiresAt===null)throw new RuntimeException($requirement['name'].' is defined as expiring. Enter an expiration date.');
        if($note!==null&&mb_strlen($note)>1000)throw new RuntimeException('Keep verification notes under 1,000 characters.');
        $db->beginTransaction();try{$beforeStmt=$db->prepare('SELECT id,status,completed_at,expires_at,verified_by_user_id FROM volunteer_credentials WHERE user_id=:user AND requirement_id=:requirement FOR UPDATE');$beforeStmt->execute(['user'=>$userId,'requirement'=>$requirementId]);$before=$beforeStmt->fetch();$stmt=$db->prepare("INSERT INTO volunteer_credentials (user_id,requirement_id,status,completed_at,expires_at,verified_by_user_id) VALUES (:user,:requirement,'approved',:completed,:expires,:verifier) ON DUPLICATE KEY UPDATE status='approved',completed_at=VALUES(completed_at),expires_at=VALUES(expires_at),verified_by_user_id=VALUES(verified_by_user_id)");$stmt->execute(['user'=>$userId,'requirement'=>$requirementId,'completed'=>$completedDate->format('Y-m-d 12:00:00'),'expires'=>$expiresAt,'verifier'=>(int)$actor['id']]);$credentialId=$before?(int)$before['id']:(int)$db->lastInsertId();$audit=$db->prepare("INSERT INTO audit_events (actor_user_id,event_type,subject_type,subject_id,summary,metadata_json) VALUES (:actor,'volunteer.credential_verified','volunteer_credential',:id,:summary,:meta)");$audit->execute(['actor'=>(int)$actor['id'],'id'=>$credentialId,'summary'=>'Verified volunteer eligibility requirement.','meta'=>json_encode(['volunteer_user_id'=>$userId,'volunteer_name'=>$volunteer['name'],'requirement_id'=>$requirementId,'requirement_code'=>$requirement['code'],'requirement_name'=>$requirement['name'],'before'=>$before?:null,'completed_at'=>$completedDate->format('Y-m-d'),'expires_at'=>$expiresAt,'note'=>$note],JSON_THROW_ON_ERROR)]);$db->commit();}catch(Throwable $e){if($db->inTransaction())$db->rollBack();if($e instanceof RuntimeException)throw $e;throw new RuntimeException('The volunteer requirement verification could not be saved.');}
    }
    private static function adminPage(PDO $db,string $basePath,array $user):never
    {
        $volunteers=VolunteerVerificationService::volunteers($db);$productions=VolunteerVerificationService::productions($db);$requirements=$db->query('SELECT id,name,category,expires FROM volunteer_requirements ORDER BY category,name')->fetchAll();$u=static fn(string $p):string=>($basePath?:'').$p;$e=static fn(string $v):string=>htmlspecialchars($v,ENT_QUOTES,'UTF-8');$flash=self::takeFlash();$today=date('Y-m-d');$subnav=[['label'=>'Shifts','href'=>'/admin/volunteer-shifts','active'=>false],['label'=>'Requirements & training','href'=>'/admin/volunteer-development','active'=>false],['label'=>'Approval queue','href'=>'/admin/volunteer-approvals','active'=>false],['label'=>'Verification','href'=>'/admin/volunteer-verification','active'=>true]];header('Content-Type:text/html; charset=utf-8');?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Volunteer verification · CTSMD Connect</title><link rel="stylesheet" href="<?=$u('/assets/css/app.css')?>"><link rel="stylesheet" href="<?=$u('/assets/css/unified-navigation.css')?>"><link rel="stylesheet" href="<?=$u('/assets/css/volunteer-verification.css')?>"></head><body class="app-body"><div class="unified-shell"><?php AppNavigation::renderSidebar('/admin/volunteer-verification',$basePath,$user);?><main class="unified-main"><?php AppNavigation::renderHeader('Volunteer Operations','Verification & coordinators',$basePath,$subnav);?><div class="vv-page"><?php if($flash):?><div class="vv-flash <?=$e($flash['type'])?>"><?=$e($flash['message'])?></div><?php endif;?><section class="vv-hero"><small>VERIFIED ELIGIBILITY & SERVICE</small><h2>Record what CTSMD has actually verified.</h2><p>Credential verification controls shift eligibility. Service verification produces formal hour records. Coordinator roles remain explicit and separate.</p></section><div class="vv-grid"><section class="vv-card"><h3>Verify requirement</h3><p>Use this for externally completed items such as background checks, facility education, certifications, or other requirements that are not completed through a Connect training module or form.</p><form method="post"><input type="hidden" name="csrf_token" value="<?=$e((string)$_SESSION['volunteer_verification_csrf'])?>"><input type="hidden" name="action" value="credential"><label>Volunteer<select name="user_id" required><?php foreach($volunteers as $v):?><option value="<?=(int)$v['id']?>"><?=$e((string)$v['name'])?></option><?php endforeach;?></select></label><label>Requirement<select name="requirement_id" required><?php foreach($requirements as $r):?><option value="<?=(int)$r['id']?>"><?=$e((string)$r['name'])?> · <?=$e((string)$r['category'])?><?=$r['expires']?' · expires':''?></option><?php endforeach;?></select></label><label>Completed / verified date<input type="date" name="completed_at" value="<?=$e($today)?>" required></label><label>Expiration date <span>required for expiring requirements</span><input type="date" name="expires_at"></label><label>Internal verification note<input name="note" maxlength="1000" placeholder="Background check confirmation, facility orientation record…"></label><button class="button" type="submit">Verify requirement</button></form><a href="<?=$u('/admin/volunteer-development')?>">Define requirements & training →</a></section><section class="vv-card"><h3>Issue service verification</h3><form method="post"><input type="hidden" name="csrf_token" value="<?=$e((string)$_SESSION['volunteer_verification_csrf'])?>"><input type="hidden" name="action" value="issue"><label>Volunteer<select name="user_id" required><?php foreach($volunteers as $v):?><option value="<?=(int)$v['id']?>"><?=$e((string)$v['name'])?></option><?php endforeach;?></select></label><label>Start date<input type="date" name="period_start" required></label><label>End date<input type="date" name="period_end" required></label><label>Purpose<input name="purpose" maxlength="190" placeholder="School service hours, recognition…"></label><button class="button" type="submit">Issue verified record</button></form></section><section class="vv-card"><h3>Assign coordinator role</h3><p>Leadership is explicit—it is never inferred from hours worked.</p><form method="post"><input type="hidden" name="csrf_token" value="<?=$e((string)$_SESSION['volunteer_verification_csrf'])?>"><input type="hidden" name="action" value="coordinator"><label>Volunteer<select name="user_id" required><?php foreach($volunteers as $v):?><option value="<?=(int)$v['id']?>"><?=$e((string)$v['name'])?></option><?php endforeach;?></select></label><label>Coordinator title<input name="title" maxlength="190" required placeholder="Front of House Coordinator"></label><label>Category<input name="category" maxlength="100" placeholder="Front of House"></label><label>Production<select name="production_id"><option value="">CTSMD organization-wide</option><?php foreach($productions as $p):?><option value="<?=(int)$p['id']?>"><?=$e((string)$p['title'])?><?=$p['season']?' · '.$e((string)$p['season']):''?></option><?php endforeach;?></select></label><button class="button" type="submit">Assign coordinator role</button></form></section></div></div></main></div><script src="<?=$u('/assets/js/unified-navigation.js')?>"></script></body></html><?php exit;
    }
    private static function memberPage(PDO $db,string $basePath,array $user):never
    {
        $rows=VolunteerVerificationService::verificationsForUser($db,(int)$user['id']);$roles=VolunteerVerificationService::coordinatorAssignments($db,(int)$user['id']);$u=static fn(string $p):string=>($basePath?:'').$p;$e=static fn(string $v):string=>htmlspecialchars($v,ENT_QUOTES,'UTF-8');header('Content-Type:text/html; charset=utf-8');?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Service verification · CTSMD Connect</title><link rel="stylesheet" href="<?=$u('/assets/css/app.css')?>"><link rel="stylesheet" href="<?=$u('/assets/css/unified-navigation.css')?>"><link rel="stylesheet" href="<?=$u('/assets/css/volunteer-verification.css')?>"></head><body class="app-body"><div class="unified-shell"><?php AppNavigation::renderSidebar('/volunteer/verifications',$basePath,$user);?><main class="unified-main"><?php AppNavigation::renderHeader('Volunteer','Service verification',$basePath);?><div class="vv-page"><section class="vv-hero"><small>CTSMD VERIFIED</small><h2>Service records you can actually use.</h2><p>Issued records are snapshots of CTSMD-verified service hours and remain available after productions close.</p></section><div class="vv-grid"><section class="vv-card"><h3>Issued verifications</h3><?php if(!$rows):?><p>No formal service verifications have been issued yet.</p><?php endif;?><?php foreach($rows as $r):?><a class="vv-record" href="<?=$u('/volunteer/verification?id='.(int)$r['id'])?>"><span><b><?=$e((string)$r['verification_code'])?></b><small><?=date('M j, Y',strtotime((string)$r['period_start']))?> – <?=date('M j, Y',strtotime((string)$r['period_end']))?> · <?=number_format(((int)$r['verified_minutes'])/60,1)?>h</small></span><em><?=$e(ucfirst((string)$r['status']))?></em></a><?php endforeach;?></section><section class="vv-card"><h3>Leadership & coordinator service</h3><?php if(!$roles):?><p>No coordinator roles are recorded.</p><?php endif;?><?php foreach($roles as $role):?><div class="vv-record static"><span><b><?=$e((string)$role['title'])?></b><small><?=$role['production_title']?$e((string)$role['production_title']):'CTSMD'?><?=$role['category']?' · '.$e((string)$role['category']):''?></small></span><em><?=$e(ucfirst((string)$role['status']))?></em></div><?php endforeach;?></section></div></div></main></div><script src="<?=$u('/assets/js/unified-navigation.js')?>"></script></body></html><?php exit;
    }
    private static function letter(string $basePath,array $user,array $v,bool $print):never
    {
        $u=static fn(string $p):string=>($basePath?:'').$p;$e=static fn(string $x):string=>htmlspecialchars($x,ENT_QUOTES,'UTF-8');header('Content-Type:text/html; charset=utf-8');?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=$e((string)$v['verification_code'])?> · CTSMD Service Verification</title><link rel="stylesheet" href="<?=$u('/assets/css/volunteer-verification.css')?>"></head><body class="vv-letter"><main><header><strong>CHILDREN’S THEATRE OF SOUTHERN MARYLAND</strong><span>Volunteer Service Verification</span></header><h1>Verification of Community Service</h1><p>This record certifies that <b><?=$e((string)$v['volunteer_name'])?></b> completed <b><?=number_format(((int)$v['verified_minutes'])/60,1)?> verified volunteer hours</b> recorded by Children’s Theatre of Southern Maryland between <?=date('F j, Y',strtotime((string)$v['period_start']))?> and <?=date('F j, Y',strtotime((string)$v['period_end']))?>.</p><?php if($v['purpose']):?><p><b>Purpose:</b> <?=$e((string)$v['purpose'])?></p><?php endif;?><section><h2>Verified service</h2><?php foreach($v['snapshot'] as $item):?><div><span><?=date('M j, Y',strtotime((string)$item['served_at']))?> · <?=$e((string)$item['production'])?> · <?=$e((string)$item['shift'])?></span><b><?=number_format(((int)$item['minutes'])/60,1)?>h</b></div><?php endforeach;?></section><footer><p><b>Verified by:</b> <?=$e((string)$v['verifier_name'])?><br><b>Issued:</b> <?=date('F j, Y',strtotime((string)$v['verified_at']))?><br><b>Verification code:</b> <?=$e((string)$v['verification_code'])?></p><p>This document was generated from CTSMD Connect’s verified volunteer service ledger.</p></footer><?php if(!$print):?><div class="vv-letter-actions"><a href="<?=$u('/volunteer/verifications')?>">Back</a><a href="<?=$u('/volunteer/verification?id='.(int)$v['id'].'&print=1')?>" target="_blank">Print / Save PDF</a></div><?php else:?><script>window.addEventListener('load',()=>window.print());</script><?php endif;?></main></body></html><?php exit;
    }
    private static function flash(string $type,string $message):void{$_SESSION['vv_flash']=['type'=>$type,'message'=>$message];}private static function takeFlash():?array{$f=$_SESSION['vv_flash']??null;unset($_SESSION['vv_flash']);return is_array($f)?$f:null;}private static function redirect(string $url):never{header('Location: '.$url,true,303);exit;}
}
